func fileProtectionFileTypesWrapperValue(owned fileProtectionFileTypesOwnedList, subItemOwnedMasks map[string][]bool) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if !owned.Set {
		return types.ObjectNull(fileProtectionFileTypesWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(owned.Items))
	for _, item := range owned.Items {
		objectValues := map[string]attr.Value{}
		tidValue := types.StringNull()
		if item.Tid != nil {
			tidValue = types.StringValue(*item.Tid)
		}
		objectValues["tid"] = tidValue
		typeValue := types.StringNull()
		if item.Type != nil {
			typeValue = types.StringValue(*item.Type)
		}
		objectValues["type"] = typeValue
		object, objectDiagnostics := types.ObjectValue(fileProtectionFileTypesItemAttributeTypes, objectValues)
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: fileProtectionFileTypesItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(fileProtectionFileTypesWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
func fileProtectionDecodeIndex(raw json.RawMessage, location string, idxKind string, diagnostics *diag.Diagnostics) (int, bool) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || fileProtectionJSONNull(trimmed) {
		diagnostics.AddError("Malformed file protection result", location+" did not contain a non-null integer idx.")
		return 0, false
	}
	if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
		diagnostics.AddError("Malformed file protection result", location+" contained a non-integer idx.")
		return 0, false
	}
	var number json.Number
	if err := json.Unmarshal(trimmed, &number); err != nil {
		diagnostics.AddError("Malformed file protection result", location+" contained a non-integer idx.")
		return 0, false
	}
	value64, err := number.Int64()
	if err != nil || value64 <= 0 || int64(int(value64)) != value64 {
		diagnostics.AddError("Malformed file protection result", location+" contained an idx that was not a positive integer.")
		return 0, false
	}
	return int(value64), true
}
