func fileProtectionJSONNull(raw json.RawMessage) bool {
	return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
}

// RejectItemNullUnlessNullable reports a malformed-result diagnostic when a
// collection-item field is present in the remote response as an explicit JSON
// null but the pinned schema does not mark the field nullable. A missing key
// is not rejected here (optional omission is handled by the decode helpers).
func fileProtectionRejectItemNullUnlessNullable(object map[string]json.RawMessage, key string, allowNull bool, location string, diagnostics *diag.Diagnostics) {
	raw, ok := object[key]
	if !ok {
		return
	}
	if fileProtectionJSONNull(raw) && !allowNull {
		diagnostics.AddError("Malformed file protection result", location+" "+key+" was null, which the pinned schema does not mark nullable.")
	}
}
